import{z as o,x as l,o as A,c,q as t,j as r,D as e,d as E,s as i,S as n,b as s}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"缓存的层次","description":"","frontmatter":{"title":"缓存的层次","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/st-cache-tiers.md","filePath":"cs/st-cache-tiers.md","lastUpdated":1791413859000}'),C={name:"cs/st-cache-tiers.md"};function D(m,a,d,h,p,u){const B=l("Mermaid");return A(),c("div",null,[a[2]||(a[2]=t('<h1 id="缓存的层次" tabindex="-1">缓存的层次 <a class="header-anchor" href="#缓存的层次" aria-label="Permalink to &quot;缓存的层次&quot;">​</a></h1><div class="epigraph"><p>存储栈上每一层缓存都有自己的主人：硬件管 CPU 缓存，内核管页缓存，数据库管缓冲池，应用管分布式缓存。层是各自为政的，拼起来的图才是一等研究对象。</p><footer>—— 据 Denning, CACM 1968；*OSTEP*；InnoDB 与 PostgreSQL I/O 文档整理</footer></div><p><a href="/cs/st-compressed-columnar">上一课</a>收在列块的编码-压缩栈。栈的两头都是缓存：热页在 CPU 缓存里也在缓冲池里，页在缓冲池里也可能在页缓存里，热点键还在另一台机器的缓存里。主干已有各层的单课：<a href="/cs/page-cache">页缓存</a>、<a href="/cs/buffer-pool-lru-k">缓冲池 LRU-K</a>、<a href="/cs/bcache">bcache</a>、<a href="/cs/cdn-cache-hierarchy">CDN 缓存层次</a>。本课不重讲单层，把层叠起来，回答两个只有叠起来才存在的问题：同一份数据被两层缓存的双重浪费怎么办、写怎么保证跨层一致。后课默认：层间决策（准入、旁路、绕开）与层内替换同样是设计对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单层视角有两个盲区。盲区一是双重缓存：数据库缓冲池与内核页缓存各存一份热点页，内存减半、替换策略互相看不见。PostgreSQL 走缓冲 I/O 把替换交给操作系统；InnoDB 可用 O_DIRECT 绕开页缓存。<span class="marginnote">术语翻译：O_DIRECT 就是让数据库跳过内核页缓存、自己管缓存的手段，用来避免同一页在内存里存两份；代价是放弃内核的预读与读合并，预取得自己补。</span>绕开拿回的是「内存只存一份、写回时机可控」，付出去的是内核的预读与共享缓存。两条路都成立，唯独「两层都全量缓存」是纯粹的浪费——这笔浪费在内存对账时以「缓存命中率虚高、实际穿透更多」的面目出现。盲区二是写路径：WAL 顺序写进页缓存，提交要 fsync 落盘，脏数据页异步回写；层与层之间「已见」的顺序必须用写屏障钉住，断电重放时才有一个一致的根——这些机制主干已钉，本课要的是层间的账。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先画图再算账。同一份数据从快到慢经过：CPU 缓存（硬件自动，纳秒）、页缓存（内核，按文件偏移）、缓冲池（数据库，按页号，可与页缓存二选一或叠加）、设备侧缓存与 SLC 区（FTL 管理）、分布式缓存（应用管理，按键，跨网络）、CDN（边缘，按 URL）。每层有自己的替换策略与准入规则，且互相不可见。期望延迟按穿透概率复合：若命中代价 \\(0.1\\ \\mu s\\)、下层设备 \\(100\\ \\mu s\\)，命中率 \\(99\\%\\) 时平均约 \\(1\\ \\mu s\\)，\\(98\\%\\) 时约 \\(2\\ \\mu s\\)——每差一个百分点，平均延迟翻一倍。<span class="marginnote">数字实例：命中代价 \\(0.1\\ \\mu s\\)、下层 \\(100\\ \\mu s\\) 时，命中率 \\(99\\%\\) 的平均延迟约 \\(0.99 \\times 0.1 + 0.01 \\times 100 \\approx 1.09\\ \\mu s\\)；掉到 \\(98\\%\\) 就约 \\(2\\ \\mu s\\)。命中率每掉一个点，平均延迟几乎翻倍，这就是 miss 税的复合方式。</span>容量规划因此先算 miss 税：一层 \\(20\\ \\mu s\\) 级的 SSD 缓存值得插入，当且仅当它吃掉的 miss 比例乘以DRAM 层的 miss 代价，大于它自己引入的复杂度。</p>',7)),(A(),r(n,null,{default:e(()=>[i(B,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20CPU%5B%22CPU%20%E7%BC%93%E5%AD%98%EF%BC%9A%E7%A1%AC%E4%BB%B6%E7%AE%A1%22%5D%20--%3E%20PG%5B%22%E9%A1%B5%E7%BC%93%E5%AD%98%EF%BC%9A%E5%86%85%E6%A0%B8%E7%AE%A1%22%5D%0A%20%20PG%20--%3E%20BP%7B%22%E7%BC%93%E5%86%B2%E6%B1%A0%EF%BC%9ADB%20%E7%AE%A1%22%7D%0A%20%20BP%20--%3E%7C%22%E8%B5%B0%E7%BC%93%E5%86%B2%20I%2FO%22%7C%20SH%5B%22%E4%B8%8E%E9%A1%B5%E7%BC%93%E5%AD%98%E5%85%B1%E4%BA%AB%E9%A1%B5%22%5D%0A%20%20BP%20--%3E%7C%22O_DIRECT%22%7C%20BY%5B%22%E7%BB%95%E5%BC%80%E9%A1%B5%E7%BC%93%E5%AD%98%E7%9B%B4%E8%BE%BE%E8%AE%BE%E5%A4%87%22%5D%0A%20%20BP%20--%3E%20DEV%5B%22%E8%AE%BE%E5%A4%87%E7%BC%93%E5%AD%98%2FSLC%EF%BC%9AFTL%20%E7%AE%A1%22%5D%0A%20%20DEV%20--%3E%20DISK%5B%22NAND%22%5D%0A%20%20APP%5B%22%E5%88%86%E5%B8%83%E5%BC%8F%E7%BC%93%E5%AD%98%EF%BC%9A%E5%BA%94%E7%94%A8%E7%AE%A1%22%5D%20-.-%3E%7C%22%E7%83%AD%E7%82%B9%E9%94%AE%E6%97%81%E8%B7%AF%22%7C%20BP%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[E("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,[E("层间决策的机制有三种名字。准入：什么值得进这一层——bcache 对顺序流旁路，防止一次全表扫描把热页冲走，与缓冲池对付扫描用 LRU-K 是同一问题在层间的投影。"),s("span",{class:"marginnote"},"直觉类比：全表扫描像洪水过库——每一页都来一次、都不会再来；若照单收进缓存，真正的热页反而被冲走。bcache 的旁路就是给洪水开泄洪道：识别出「只来一次」的流直接放去下游，不给缓存添乱。"),E("旁路：O_DIRECT 绕开页缓存、DAX 直接映射持久内存，绕开的本质是把这一层的职责合并进上一层，减少一次翻译与一份副本。写一致：各层副本的先后由写路径纪律保证——WAL 先落、脏页后回、屏障钉序，任何一层都不能自行「提前可见」到破坏这个顺序的程度；读路径不广播失效，因为单机内层间的失配靠重读自然修复，跨机的失效才需要协议（分布式缓存失效另课已钉）。层存在的合法性统一成一个判据：这一层比下一层快得多、比上一层大得多，且有人愿意为它的替换策略负责。")],-1)),(A(),r(n,null,{default:e(()=>[i(B,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E4%BA%8B%E5%8A%A1%E5%86%99%22%5D%20--%3E%20WAL%5B%22WAL%20%E9%A1%BA%E5%BA%8F%E5%86%99%E8%BF%9B%E9%A1%B5%E7%BC%93%E5%AD%98%22%5D%0A%20%20WAL%20--%3E%20FS%5B%22commit%20%E5%89%8D%20fsync%22%5D%0A%20%20FS%20--%3E%20OK%7B%22fsync%20%E5%AE%8C%E6%88%90%EF%BC%9F%22%7D%0A%20%20OK%20--%3E%7C%22%E5%90%A6%22%7C%20WAIT%5B%22%E6%8F%90%E4%BA%A4%E4%B8%8D%E5%8F%AF%E8%A7%81%EF%BC%8C%E7%BB%A7%E7%BB%AD%E7%AD%89%22%5D%0A%20%20OK%20--%3E%7C%22%E6%98%AF%22%7C%20VIS%5B%22%E6%8F%90%E4%BA%A4%E5%AF%B9%E5%A4%96%E5%8F%AF%E8%A7%81%22%5D%0A%20%20VIS%20--%3E%20DP%5B%22%E8%84%8F%E6%95%B0%E6%8D%AE%E9%A1%B5%E5%BC%82%E6%AD%A5%E5%9B%9E%E5%86%99%22%5D%0A%20%20DP%20--%3E%20BAR%5B%22%E5%86%99%E5%B1%8F%E9%9A%9C%EF%BC%9AWAL%20%E5%85%88%E4%BA%8E%E8%84%8F%E9%A1%B5%E8%90%BD%E7%9B%98%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">数字锚点：DRAM 约 \\(100\\ \\mu s\\) 的百分之一、NVMe 读约 \\(10\\)–\\(100\\ \\mu s\\)、跨机缓存往返 \\(0.1\\)–\\(1\\ ms\\)——每层的延迟差是两到三个数量级，所以命中率报表上一个小数点的挪动，等价于换一代硬件。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲单层机制：页缓存的回写、缓冲池的 pin 与 latch、bcache 的 writeback、CDN 的失效各有专课；CPU 缓存的实现与假名另属体系结构课；分布式缓存的一致性协议不展开。本课钉的是层间的三张决策：准入、旁路、写序。后课默认：单机栈的层次图已经拼完。下一课把这页纸带进集群：单机的页、日志与格式在分布式里如何成为四个案例。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>每层缓存有各自的主人、策略与盲区；层间图是研究对象，单层机制是前置。</li><li>双重缓存必须表态：缓冲 I/O 或 O_DIRECT 二选一，两层全量缓存是纯浪费。</li><li>期望延迟按 miss 概率复合：命中率差一个百分点，平均延迟可以差一倍。</li><li>层间三决策：准入（防扫描污染）、旁路（减少翻译与副本）、写序（屏障钉住跨层顺序）。</li><li>出处：Denning, CACM 1968；<em>OSTEP</em>；InnoDB、PostgreSQL I/O 文档；Linux page cache 语义。</li></ul>',5))])}const _=o(C,[["render",D]]);export{f as __pageData,_ as default};
